SourceCode.Declaration:
/// <summary>
/// Provides helpers to retrieve and apply product attribute values for an item.
/// Handles retrieval using cached MET attributes when configured, or falls back
/// to reading attributes from the associated `InventTable`.
/// </summary>
class METGetAttributeValue
{
    InventTable inventTable;

}

Method.Source:
/// <summary>
/// Gets or sets the associated `InventTable` for this instance.
/// </summary>
/// <param name="_inventTable">Optional `InventTable` to assign.</param>
/// <returns>The current `InventTable` instance used by this object.</returns>
public InventTable parmInventTable(InventTable _inventTable = inventTable)
{
    inventTable = _inventTable;
    return inventTable;
}

/// <summary>
/// Protected default constructor. Use the provided factory methods to create instances.
/// </summary>
protected void new()
{
}

/// <summary>
/// Constructs and returns a new `METGetAttributeValue` instance.
/// </summary>
/// <returns>A newly constructed `METGetAttributeValue` object.</returns>
private static METGetAttributeValue construct()
{
    return new METGetAttributeValue();
}

/// <summary>
/// Creates a new `METGetAttributeValue` instance and initializes it with the provided `InventTable`.
/// </summary>
/// <param name="_inventTable">The `InventTable` to associate with the new instance.</param>
/// <returns>A `METGetAttributeValue` instance with its `inventTable` set to `_inventTable`.</returns>
public static METGetAttributeValue newFromInventTable(InventTable _inventTable)
{
    METGetAttributeValue getAttributeValue;

    getAttributeValue = METGetAttributeValue::construct();
    getAttributeValue.parmInventTable(_inventTable);

    return getAttributeValue;
}

/// <summary>
/// Retrieves the value of a product attribute for the specified item.
/// Uses cached MET attribute values when configured and when the MET attribute
/// is marked as calculated; otherwise, it reads the attribute from the related `InventTable`.
/// </summary>
/// <param name="_itemId">Item identifier to locate the product (used to find `METInventTable` and/or `InventTable`).</param>
/// <param name="_attributeRecId">The attribute identifier to retrieve.</param>
/// <returns>
/// The attribute value as `anytype`. The concrete runtime type depends on the attribute:
/// boolean values for attributes such as `PricedByWeight` and `ConsumerGSTExempt`, or
/// text values for attributes such as `LevyType` and `InvoiceCategory`.
/// </returns>
public anytype getAttributeValue(RecId _attibuteRecId)
{
    anytype                 attributeValue;
    METInventTable          metInventTable = METInventTable::find(inventTable.ItemId);
    EcoResProductParameters ecoResProductParameters = EcoResProductParameters::find();

    if (ecoResProductParameters.METUseCachedAttributes == METUseCachedAttributesEnum::Yes
        && metInventTable.IsAttributeCalculated == NoYes::Yes)
    {
        switch (_attibuteRecId)
        {
            case ecoResProductParameters.METPricedByWeight:
                attributeValue = metInventTable.PricedByWeight;
                break;
            case ecoResProductParameters.METLevyType:
                attributeValue = metInventTable.LevyType;
                break;
            case ecoResProductParameters.METInvoiceCategory:
                attributeValue = metInventTable.InvoiceCategory;
                break;
            case ecoResProductParameters.METConsumerGSTExempt:
                attributeValue = metInventTable.ConsumerGSTExempt;
                break;
        }
    }
    else
    {
        switch (_attibuteRecId)
        {
            case ecoResProductParameters.METPricedByWeight, ecoResProductParameters.METConsumerGSTExempt:
                attributeValue = inventTable.getProductBooleanAttributeVal(_attibuteRecId);
                break;
            case ecoResProductParameters.METLevyType, ecoResProductParameters.METInvoiceCategory:
                attributeValue = inventTable.getProductTextAttribueVal(_attibuteRecId);
                break;
        }
    }

    return attributeValue;
}

/// <summary>
/// Applies attribute values to the associated `InventTable` based on the provided display information.
/// This operation only executes when cached attribute usage is enabled or configured as NoTrackValues.
/// </summary>
/// <param name="_ecoResProductParameters">Product parameters that control which MET attributes are applied.</param>
/// <param name="_displayInfoOnUpdate">Display/update information used to set attribute values on `InventTable`.</param>
public void setAttributeValues(EcoResProductParameters _ecoResProductParameters, METDisplayInfoOnUpdate _displayInfoOnUpdate = false)
{
    if (_ecoResProductParameters.METUseCachedAttributes == METUseCachedAttributesEnum::Yes
        || _ecoResProductParameters.METUseCachedAttributes == METUseCachedAttributesEnum::NoTrackValues)
    {
        inventTable.setAttributeValues(_ecoResProductParameters, _displayInfoOnUpdate);
    }
}
